import ts from "typescript";

export const GENERATED_NOTICE =
  "// AUTO-GENERATED FROM contracts/source/deck-api.contract.ts\n" +
  "// Do not edit this file directly.\n\n";

function titleCase(name) {
  return name.slice(0, 1).toUpperCase() + name.slice(1);
}

function isExported(node) {
  return Boolean(node.modifiers?.some((modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword));
}

function fieldNameText(name) {
  if (ts.isIdentifier(name) || ts.isStringLiteral(name) || ts.isNumericLiteral(name)) {
    return name.text;
  }
  throw new Error(`Unsupported property name: ${name.getText()}`);
}

function goFieldName(name) {
  const words = name
    .replace(/[^A-Za-z0-9]+/g, " ")
    .split(" ")
    .filter(Boolean);
  if (words.length === 0) {
    return "Field";
  }
  return words.map(titleCase).join("");
}

function isNullishType(node) {
  return (
    node.kind === ts.SyntaxKind.NullKeyword ||
    node.kind === ts.SyntaxKind.UndefinedKeyword ||
    (ts.isLiteralTypeNode(node) &&
      (node.literal.kind === ts.SyntaxKind.NullKeyword ||
        node.literal.kind === ts.SyntaxKind.UndefinedKeyword))
  );
}

function isStringLikeType(node) {
  if (node.kind === ts.SyntaxKind.StringKeyword) {
    return true;
  }
  if (ts.isLiteralTypeNode(node) && ts.isStringLiteral(node.literal)) {
    return true;
  }
  if (ts.isIntersectionTypeNode(node)) {
    return node.types.some((part) => part.kind === ts.SyntaxKind.StringKeyword);
  }
  return false;
}

function typeReferenceName(node) {
  return node.typeName.getText();
}

function recordGoType(node, sourceFile) {
  const args = node.typeArguments;
  if (!args || args.length !== 2) {
    return "map[string]any";
  }
  const key = args[0];
  const value = args[1];
  if (key.kind !== ts.SyntaxKind.StringKeyword) {
    return "map[string]any";
  }
  return `map[string]${toGoType(value, sourceFile)}`;
}

export function toGoType(node, sourceFile) {
  if (!node) {
    return "any";
  }

  switch (node.kind) {
    case ts.SyntaxKind.StringKeyword:
      return "string";
    case ts.SyntaxKind.BooleanKeyword:
      return "bool";
    case ts.SyntaxKind.NumberKeyword:
      return "float64";
    case ts.SyntaxKind.UnknownKeyword:
    case ts.SyntaxKind.AnyKeyword:
      return "any";
    case ts.SyntaxKind.ObjectKeyword:
      return "map[string]any";
    default:
      break;
  }

  if (ts.isArrayTypeNode(node)) {
    return `[]${toGoType(node.elementType, sourceFile)}`;
  }

  if (ts.isParenthesizedTypeNode(node)) {
    return toGoType(node.type, sourceFile);
  }

  if (ts.isLiteralTypeNode(node)) {
    if (ts.isStringLiteral(node.literal)) {
      return "string";
    }
    if (ts.isNumericLiteral(node.literal)) {
      return "float64";
    }
    if (
      node.literal.kind === ts.SyntaxKind.TrueKeyword ||
      node.literal.kind === ts.SyntaxKind.FalseKeyword
    ) {
      return "bool";
    }
    return "any";
  }

  if (ts.isTypeReferenceNode(node)) {
    const name = typeReferenceName(node);
    if (name === "Array" && node.typeArguments?.length === 1) {
      return `[]${toGoType(node.typeArguments[0], sourceFile)}`;
    }
    if (name === "Record") {
      return recordGoType(node, sourceFile);
    }
    return name;
  }

  if (ts.isUnionTypeNode(node)) {
    const parts = node.types.filter((part) => !isNullishType(part));
    if (parts.length === 0) {
      return "any";
    }
    if (parts.every(isStringLikeType)) {
      return "string";
    }
    const rendered = parts.map((part) => toGoType(part, sourceFile));
    if (rendered.every((part) => part === rendered[0])) {
      return rendered[0];
    }
    return "any";
  }

  if (ts.isIntersectionTypeNode(node)) {
    if (node.types.some((part) => part.kind === ts.SyntaxKind.StringKeyword)) {
      return "string";
    }
    return "any";
  }

  if (ts.isIndexedAccessTypeNode(node)) {
    return "string";
  }

  if (ts.isTypeLiteralNode(node)) {
    return "map[string]any";
  }

  return node.getText(sourceFile);
}

function isNullableStructRef(typeNode) {
  if (!typeNode || !ts.isUnionTypeNode(typeNode)) {
    return false;
  }
  const hasNull = typeNode.types.some((part) => isNullishType(part));
  if (!hasNull) {
    return false;
  }
  const nonNull = typeNode.types.filter((part) => !isNullishType(part));
  if (nonNull.length !== 1) {
    return false;
  }
  const head = nonNull[0];
  if (!ts.isTypeReferenceNode(head)) {
    return false;
  }
  const refName = typeReferenceName(head);
  // Record<...> / Array<...> resolve to map / slice on the Go side; those
  // are already nilable on the wire, so a pointer is unnecessary.
  return refName !== "Record" && refName !== "Array";
}

function renderStructFields(members, sourceFile) {
  return members.filter(ts.isPropertySignature).map((member) => {
    const fieldName = fieldNameText(member.name);
    const goName = goFieldName(fieldName);
    let goType = toGoType(member.type, sourceFile);
    // Nullable struct refs (`SomeStruct | null`) become Go pointers so
    // consumers can express "null on the wire" via nil; required for
    // contract-typing correctness when the DTO is a struct, not a map.
    if (isNullableStructRef(member.type)) {
      goType = `*${goType}`;
    }
    const omitEmpty = member.questionToken ? ",omitempty" : "";
    return `\t${goName} ${goType} \`json:"${fieldName}${omitEmpty}"\``;
  });
}

function renderInterface(node, sourceFile) {
  const name = node.name.text;
  const fields = renderStructFields(node.members, sourceFile);
  return `type ${name} struct {\n${fields.join("\n")}\n}`;
}

function renderTypeAlias(node, sourceFile) {
  const name = node.name.text;
  const type = node.type;
  if (ts.isTypeLiteralNode(type)) {
    const fields = renderStructFields(type.members, sourceFile);
    return `type ${name} struct {\n${fields.join("\n")}\n}`;
  }
  if (ts.isIntersectionTypeNode(type)) {
    const literal = type.types.find(ts.isTypeLiteralNode);
    if (literal) {
      const fields = renderStructFields(literal.members, sourceFile);
      return `type ${name} struct {\n${fields.join("\n")}\n}`;
    }
  }
  if (
    ts.isUnionTypeNode(type) &&
    type.types.filter((part) => !isNullishType(part)).every(isStringLikeType)
  ) {
    return `type ${name} string`;
  }
  if (type.kind === ts.SyntaxKind.StringKeyword) {
    return `type ${name} string`;
  }
  if (type.kind === ts.SyntaxKind.BooleanKeyword) {
    return `type ${name} bool`;
  }
  if (type.kind === ts.SyntaxKind.NumberKeyword) {
    return `type ${name} float64`;
  }
  if (ts.isTypeReferenceNode(type)) {
    return `type ${name} = ${typeReferenceName(type)}`;
  }
  return `type ${name} ${toGoType(type, sourceFile)}`;
}

export function parseContractSource(source, fileName = "deck-api.contract.ts") {
  const sourceFile = ts.createSourceFile(
    fileName,
    source,
    ts.ScriptTarget.Latest,
    true,
    ts.ScriptKind.TS,
  );
  const declarations = [];

  for (const node of sourceFile.statements) {
    if (!isExported(node)) {
      continue;
    }
    if (ts.isInterfaceDeclaration(node)) {
      declarations.push({
        kind: "interface",
        name: node.name.text,
        node,
      });
      continue;
    }
    if (ts.isTypeAliasDeclaration(node)) {
      declarations.push({
        kind: "type",
        name: node.name.text,
        node,
      });
    }
  }

  return { declarations, sourceFile };
}

export function renderTypescript(source) {
  return `${GENERATED_NOTICE}${source}`;
}

export function renderGo(source) {
  const contract = parseContractSource(source);
  const goBodies = contract.declarations.map((declaration) => {
    if (declaration.kind === "interface") {
      return renderInterface(declaration.node, contract.sourceFile);
    }
    return renderTypeAlias(declaration.node, contract.sourceFile);
  });

  return `${GENERATED_NOTICE}package deckapi\n\n${goBodies.join("\n\n")}\n`;
}

export function renderDeckApiArtifacts(source) {
  return {
    go: renderGo(source),
    ts: renderTypescript(source),
  };
}
